DO $$ BEGIN IF has_table_privilege('authenticated', 'public.cp_order_identity', 'SELECT') THEN RAISE EXCEPTION 'authenticated still has direct identity table access'; END IF; IF NOT has_function_privilege('authenticated', (SELECT p.oid FROM pg_proc p JOIN pg_namespace n ON n.oid=p.pronamespace WHERE n.nspname='public' AND p.proname='get_counterparty_completed_order_count' LIMIT 1), 'EXECUTE') THEN RAISE EXCEPTION 'authenticated cannot execute protected counterparty count'; END IF; END $$;